47	// mutationIsolationConfig 是这组场景的地图配置：原点初始位姿、非零
48	// 初始方差、合并上限 5。
49	func mutationIsolationConfig() Config {
50		return Config{InitialTime: 0, InitialVariance: 1.0, MaxInterval: 1000, MergeDistance: 5.0}
51	}
52	
53	// mutationIsolationSegment 构造上述带非零朝向、运动后观测、跨帧同一
54	// 路标与同帧有序重复观测的合法轨迹，并返回各帧指针供调用方事后改写。
55	func mutationIsolationSegment() (Segment, *Frame, *Frame, *Frame, *Frame) {
56		seg := Segment{
57			ID: "seg",
58			Frames: []Frame{
59				{Time: 50, DX: 1, DY: 0, DHeading: 0, MoveVariance: 0.1},
60				{
61					Time: 100, DX: 3, DY: 0, DHeading: math.Pi / 2, MoveVariance: 0.2,
62					Observations: []Observation{
63						{ID: "L", X: 0, Y: -1},
64						{ID: "M", X: 0, Y: 1},
65					},
66				},
67				{
68					Time: 200, DX: 4, DY: 0, DHeading: 0, MoveVariance: 0.4,
69					Observations: []Observation{
70						{ID: "L", X: 0, Y: 0},
71						{ID: "L", X: 1, Y: 0},
72					},
73				},
74				{Time: 300, DX: 0, DY: 0, DHeading: 0, MoveVariance: 0.5},
75			},
76		}
77		return seg, &seg.Frames[0], &seg.Frames[1], &seg.Frames[2], &seg.Frames[3]
78	}
