80	// expectPose 断言查询到的位姿在时间与各数值字段上都接近期望。
81	func expectPose(t *testing.T, what string, got, want Pose) {
82		t.Helper()
83		if got.Time != want.Time {
84			t.Fatalf("%s time = %d, want %d (pose %+v)", what, got.Time, want.Time, got)
85		}
86		approxEq(t, what+" x", got.X, want.X)
87		approxEq(t, what+" y", got.Y, want.Y)
88		approxEq(t, what+" heading", got.Heading, want.Heading)
89		approxEq(t, what+" variance", got.Variance, want.Variance)
90	}
