92	// expectPoseChange 断言校正记录中一帧的校正前后值与期望一致。
93	func expectPoseChange(t *testing.T, i int, got PoseChange, before, after Pose) {
94		t.Helper()
95		if got.Before.Time != before.Time || got.After.Time != after.Time {
96			t.Fatalf("pose change %d times = %d -> %d, want %d -> %d",
97				i, got.Before.Time, got.After.Time, before.Time, after.Time)
98		}
99		approxEq(t, "before x", got.Before.X, before.X)
100		approxEq(t, "before y", got.Before.Y, before.Y)
101		approxEq(t, "before heading", got.Before.Heading, before.Heading)
102		approxEq(t, "before variance", got.Before.Variance, before.Variance)
103		approxEq(t, "after x", got.After.X, after.X)
104		approxEq(t, "after y", got.After.Y, after.Y)
105		approxEq(t, "after heading", got.After.Heading, after.Heading)
106		approxEq(t, "after variance", got.After.Variance, after.Variance)
107	}
