109	// 调用方成功导入后就地改写原观测标识与自身坐标、调整原帧运动方差并
110	// 替换原观测列表：地图的当前位姿、各时间历史位姿、路标位置与观测次数
111	// 仍全部是导入时已接受的结果，改出的空标识/陌生路标与巨大坐标不会出现。
112	func TestImportedTrajectoryIsolatedFromCallerMutation(t *testing.T) {
113		m := newMap(t, mutationIsolationConfig())
114		seg, f50, f100, f200, f300 := mutationIsolationSegment()
115	
116		res, err := m.ImportSegment(seg)
117		if err != nil {
118			t.Fatalf("ImportSegment: %v", err)
119		}
120		// 导入结果即已接受的末位姿与路标集合。
121		expectPose(t, "import end pose", res.EndPose, Pose{Time: 300, X: 4, Y: 4, Heading: math.Pi / 2, Variance: 2.2})
122		if len(res.LandmarkIDs) != 2 || res.LandmarkIDs[0] != "L" || res.LandmarkIDs[1] != "M" {
123			t.Fatalf("import landmark ids = %v, want [L M]", res.LandmarkIDs)
124		}
125	
126		// 记录导入时已接受的位姿快照，供改写后及校正记录比对。
127		wantP0 := Pose{Time: 0, X: 0, Y: 0, Heading: 0, Variance: 1.0}
128		wantP50 := Pose{Time: 50, X: 1, Y: 0, Heading: 0, Variance: 1.1}
129		wantP100 := Pose{Time: 100, X: 4, Y: 0, Heading: math.Pi / 2, Variance: 1.3}
130		wantP200 := Pose{Time: 200, X: 4, Y: 4, Heading: math.Pi / 2, Variance: 1.7}
131		wantP300 := Pose{Time: 300, X: 4, Y: 4, Heading: math.Pi / 2, Variance: 2.2}
132	
133		// ---- 调用方复用这批输入准备下一段：就地改写一切可写字段 ----
134		// 原观测标识改成空标识、自身坐标改成远超合并距离的巨大值。
135		f100.Observations[0] = Observation{ID: "", X: 1e6, Y: 1e6}
136		f100.Observations[1] = Observation{ID: "", X: -1e6, Y: 1e6}
137		f200.Observations[0] = Observation{ID: "", X: 1e6, Y: 1e6}
138		f200.Observations[1] = Observation{ID: "", X: 1e6, Y: -1e6}
139		// 原帧运动方差改成准备下一段时填写的新值。
140		f50.MoveVariance, f100.MoveVariance, f200.MoveVariance, f300.MoveVariance = 500, 500, 500, 500
141		// 整表替换原观测列表：陌生路标标识与空标识、远离一切的坐标。
142		f100.Observations = []Observation{{ID: "ZZ", X: 1e9, Y: 1e9}}
143		f200.Observations = []Observation{{ID: "", X: 1e9, Y: 1e9}}
144	
145		// 当前位姿与相应时间的历史位姿仍是已接受结果。
146		cur, _ := m.CurrentPose()
147		expectPose(t, "current after mutation", cur, wantP300)
148		for _, want := range []Pose{wantP0, wantP50, wantP100, wantP200} {
149			p, err := m.PoseAt(want.Time)
150			if err != nil {
151				t.Fatalf("PoseAt(%d): %v", want.Time, err)
152			}
153			expectPose(t, "history after mutation", p, want)
154		}
155	
156		// 路标位置与观测次数仍是已接受结果；陌生标识 ZZ 不在地图中。
157		lms, _ := m.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
158		if len(lms) != 2 {
159			t.Fatalf("landmarks after mutation = %v, want exactly L and M", lms)
160		}
161		lBefore, ok := findLandmark(lms, "L")
162		if !ok {
163			t.Fatalf("L missing after mutation: %v", lms)
164		}
165		approxEq(t, "L x after mutation", lBefore.X, 13.0/3.0)
166		approxEq(t, "L y after mutation", lBefore.Y, 3)
167		if lBefore.Count != 3 {
168			t.Fatalf("L count after mutation = %d, want 3", lBefore.Count)
169		}
170		mBefore, ok := findLandmark(lms, "M")
171		if !ok {
172			t.Fatalf("M missing after mutation: %v", lms)
173		}
174		approxEq(t, "M x after mutation", mBefore.X, 3)
175		approxEq(t, "M y after mutation", mBefore.Y, 0)
176		if mBefore.Count != 1 {
177			t.Fatalf("M count after mutation = %d, want 1", mBefore.Count)
178		}
179		if _, err := m.LandmarkAppearances("ZZ"); !errors.Is(err, ErrLandmarkNotFound) {
180			t.Fatalf("stranger landmark ZZ appeared after mutation: %v", err)
181		}
182		hL, err := m.LandmarkAppearances("L")
183		if err != nil {
184			t.Fatal(err)
185		}
186		if len(hL.Appearances) != 1 || !hL.Appearances[0].Active ||
187			!hL.Appearances[0].HasFirstSeen || hL.Appearances[0].FirstSeenTime != 100 ||
188			hL.Appearances[0].Landmark.Count != 3 {
189			t.Fatalf("L appearance after mutation = %+v", hL.Appearances)
190		}
191	
192		// ---- 对已导入帧提交一次原本合法的回环校正 ----
193		// 空标识与 1e9 坐标若被误当作观测来源，会以 empty_id/non_finite/
194		// landmark_conflict 等原因拒绝；使用内部已接受副本时校正必须成功。
195		req := Correction{
196			ID:     "c-loop",
197			Anchor: 100,
198			Target: CorrectionTarget{X: 10, Y: 20, Heading: 0, Variance: 0.3},
199		}
200		rec, err := m.Correct(req)
201		if err != nil {
202			t.Fatalf("Correct after caller mutated input: %v", err)
203		}
204		if rec.ID != "c-loop" || rec.Anchor != 100 || rec.EndTime != 300 || rec.Target != req.Target {
205			t.Fatalf("record header = %+v", rec)
206		}
207	
208		// 更早帧不在记录中；记录覆盖锚点及之后三帧，前后值与已接受轨迹/
209		// 校正目标一致。
210		if len(rec.Poses) != 3 {
211			t.Fatalf("pose changes = %+v, want 3 (t=100,200,300)", rec.Poses)
212		}
213		wantP100After := Pose{Time: 100, X: 10, Y: 20, Heading: 0, Variance: 0.3}
214		wantP200After := Pose{Time: 200, X: 14, Y: 20, Heading: 0, Variance: 0.7}
215		wantP300After := Pose{Time: 300, X: 14, Y: 20, Heading: 0, Variance: 1.2}
216		expectPoseChange(t, 0, rec.Poses[0], wantP100, wantP100After)
217		expectPoseChange(t, 1, rec.Poses[1], wantP200, wantP200After)
218		expectPoseChange(t, 2, rec.Poses[2], wantP300, wantP300After)
219	
220		// 受影响路标按原观测及原同帧次序重放：L 三次观测 (10,19)/(14,20)/
221		// (15,20) 等权平均 (13, 59/3)，计数不变；M 一次观测 (10,21)。
222		if len(rec.Landmarks) != 2 {
223			t.Fatalf("landmark changes = %+v, want L and M", rec.Landmarks)
224		}
225		lc, mc := rec.Landmarks[0], rec.Landmarks[1]
226		if lc.ID != "L" || lc.Occurrence != 1 || mc.ID != "M" || mc.Occurrence != 1 {
227			t.Fatalf("landmark change order = %+v %+v", lc, mc)
228		}
229		if lc.Before.ID != "L" || lc.Before.Count != 3 || lc.After.Count != 3 {
230			t.Fatalf("L change counts = %+v, want 3 -> 3", lc)
231		}
232		approxEq(t, "L before x in record", lc.Before.X, 13.0/3.0)
233		approxEq(t, "L before y in record", lc.Before.Y, 3)
234		approxEq(t, "L after x in record", lc.After.X, 13)
235		approxEq(t, "L after y in record", lc.After.Y, 59.0/3.0)
236		if mc.Before.Count != 1 || mc.After.Count != 1 {
237			t.Fatalf("M change counts = %+v, want 1 -> 1", mc)
238		}
239		approxEq(t, "M before x in record", mc.Before.X, 3)
240		approxEq(t, "M before y in record", mc.Before.Y, 0)
241		approxEq(t, "M after x in record", mc.After.X, 10)
242		approxEq(t, "M after y in record", mc.After.Y, 21)
243	
244		// 查询结果与校正记录的校正后值相互一致。
245		cur, _ = m.CurrentPose()
246		expectPose(t, "current after correction", cur, wantP300After)
247		for _, want := range []Pose{wantP100After, wantP200After, wantP300After} {
248			p, _ := m.PoseAt(want.Time)
249			expectPose(t, "history after correction", p, want)
250		}
251		for _, pc := range rec.Poses {
252			p, _ := m.PoseAt(pc.After.Time)
253			expectPose(t, "pose query vs record", p, pc.After)
254		}
255		// 锚点之前的帧保持导入时结果，不采用调用方后来填写的运动方差。
256		p0, _ := m.PoseAt(0)
257		expectPose(t, "initial pose after correction", p0, wantP0)
258		p50, _ := m.PoseAt(50)
259		expectPose(t, "earlier frame after correction", p50, wantP50)
260	
261		// 区域查询只含 L、M 的校正后结果；陌生路标 ZZ 不出现。
262		lms, _ = m.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
263		if len(lms) != 2 {
264			t.Fatalf("landmarks after correction = %v, want exactly L and M", lms)
265		}
266		lAfter, ok := findLandmark(lms, "L")
267		if !ok {
268			t.Fatalf("L missing after correction: %v", lms)
269		}
270		approxEq(t, "queried L x", lAfter.X, lc.After.X)
271		approxEq(t, "queried L y", lAfter.Y, lc.After.Y)
272		if lAfter.Count != 3 {
273			t.Fatalf("queried L count = %d, want 3", lAfter.Count)
274		}
275		mAfter, ok := findLandmark(lms, "M")
276		if !ok {
277			t.Fatalf("M missing after correction: %v", lms)
278		}
279		approxEq(t, "queried M x", mAfter.X, mc.After.X)
280		approxEq(t, "queried M y", mAfter.Y, mc.After.Y)
281		if mAfter.Count != 1 {
282			t.Fatalf("queried M count = %d, want 1", mAfter.Count)
283		}
284		if _, err := m.LandmarkAppearances("ZZ"); !errors.Is(err, ErrLandmarkNotFound) {
285			t.Fatalf("stranger landmark ZZ appeared in map/records: %v", err)
286		}
287		hL, _ = m.LandmarkAppearances("L")
288		if len(hL.Appearances) != 1 || !hL.Appearances[0].Active ||
289			hL.Appearances[0].FirstSeenTime != 100 || hL.Appearances[0].Landmark.Count != 3 {
290			t.Fatalf("L appearance after correction = %+v", hL.Appearances)
291		}
292		approxEq(t, "appearance L x", hL.Appearances[0].Landmark.X, 13)
293		approxEq(t, "appearance L y", hL.Appearances[0].Landmark.Y, 59.0/3.0)
294	
295		// 保存的校正记录与返回记录一致，且只有这一条；调用方对原输入的
296		// 改写没有向记录中引入任何陌生路标或空标识。
297		recs, _ := m.Corrections()
298		if len(recs) != 1 || !recordsEqual(recs[0], rec) {
299			t.Fatalf("stored records = %+v, want single record equal to returned %+v", recs, rec)
300		}
301	}
