303	// 原观测本应在重放时引起校正冲突时，调用方事后把原数据改成看似可以
304	// 合并的位置（乃至整表替换成陌生路标）都不能改变结论：校正仍按已接受
305	// 的观测拒绝，错误给出原路标、出现编号与冲突帧时间；已有位姿、路标与
306	// 校正记录均保持不变，冲突的提交不消耗校正标识。
307	//
308	// 几何（初始位姿 (0,0)、朝向 0、合并上限 2）：
309	//
310	//	t=100：L 本地 (0,0) → 世界 (0,0)（首次建点）
311	//	t=200：L 本地 (1,0) → 世界 (1,0)（距 (0,0) 为 1，合法导入；均值 (0.5,0)）
312	//
313	// 以 t=200 为锚点平移到 (3,0)：t=100 在锚点之前，观测固定为 (0,0)；
314	// t=200 的已接受观测 (1,0) 随新位姿重放为 (4,0)，与 (0,0) 相距 4 > 2，
315	// 必须冲突。调用方若把本地坐标改成 (-2,0)，重放只会得到 (1,0)、看似
316	// 可以合并；地图必须无视这次改写。
317	func TestCorrectionConflictUsesAcceptedObservationsNotCallerMutation(t *testing.T) {
318		cfg := Config{InitialTime: 0, InitialVariance: 1.0, MaxInterval: 1000, MergeDistance: 2.0}
319		m := newMap(t, cfg)
320		seg := Segment{
321			ID: "seg",
322			Frames: []Frame{
323				{Time: 100, DX: 0, DY: 0, DHeading: 0, MoveVariance: 0,
324					Observations: []Observation{{ID: "L", X: 0, Y: 0}}},
325				{Time: 200, DX: 0, DY: 0, DHeading: 0, MoveVariance: 0,
326					Observations: []Observation{{ID: "L", X: 1, Y: 0}}},
327			},
328		}
329		if _, err := m.ImportSegment(seg); err != nil {
330			t.Fatalf("ImportSegment: %v", err)
331		}
332		f100, f200 := &seg.Frames[0], &seg.Frames[1]
333	
334		// 导入后：L 均值 (0.5,0)、计数 2；位姿停在 (0,0)。
335		lms, _ := m.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
336		if len(lms) != 1 || lms[0].ID != "L" {
337			t.Fatalf("landmarks before correction = %v", lms)
338		}
339		approxEq(t, "L x before", lms[0].X, 0.5)
340		approxEq(t, "L y before", lms[0].Y, 0)
341		if lms[0].Count != 2 {
342			t.Fatalf("L count before = %d, want 2", lms[0].Count)
343		}
344	
345		req := Correction{
346			ID:     "c-loop",
347			Anchor: 200,
348			Target: CorrectionTarget{X: 3, Y: 0, Heading: 0, Variance: 0},
349		}
350		expectConflict := func(stage string) {
351			t.Helper()
352			_, err := m.Correct(req)
353			r, ok := AsRejectError(err)
354			if !ok {
355				t.Fatalf("%s: correction err = %v, want *RejectError", stage, err)
356			}
357			if r.Kind != RejectLandmarkConflict || !r.HasTime || r.Time != 200 ||
358				!r.HasLandmark || r.Landmark != "L" || !r.HasOccurrence || r.Occurrence != 1 {
359				t.Fatalf("%s: reject = %+v, want landmark_conflict at time 200 for L occurrence 1", stage, r)
360			}
361		}
362	
363		// 原数据未被改写时，按已接受观测 (1,0) 重放得到 (4,0)，冲突。
364		expectConflict("before caller mutation")
365	
366		// 调用方把原观测改成本地 (-2,0)：重放只会得到 (1,0)，与固定观测
367		// (0,0) 相距 1，看似可以合并；同时篡改运动方差。
368		f200.Observations[0] = Observation{ID: "L", X: -2, Y: 0}
369		f100.MoveVariance, f200.MoveVariance = 90, 90
370		expectConflict("after caller mutated accepted observation")
371	
372		// 进一步把整份原观测列表替换为陌生路标 ZZ：拒绝信息仍指向原路标 L
373		// 与原冲突帧 t=200、出现 1，而不是接受校正或改报 ZZ。
374		f100.Observations = []Observation{{ID: "ZZ", X: 1e9, Y: 1e9}}
375		f200.Observations = []Observation{{ID: "ZZ", X: 0, Y: 0}}
376		expectConflict("after caller replaced observation lists")
377	
378		// 已有位姿、路标与校正记录均保持导入时结果，无任何部分更新。
379		cur, _ := m.CurrentPose()
380		expectPose(t, "current after rejected corrections", cur,
381			Pose{Time: 200, X: 0, Y: 0, Heading: 0, Variance: 1.0})
382		for _, tc := range []struct {
383			time int64
384			x    float64
385		}{
386			{0, 0}, {100, 0}, {200, 0},
387		} {
388			p, err := m.PoseAt(tc.time)
389			if err != nil {
390				t.Fatalf("PoseAt(%d): %v", tc.time, err)
391			}
392			if p.Time != tc.time || p.X != tc.x || p.Y != 0 || p.Heading != 0 {
393				t.Fatalf("PoseAt(%d) = %+v, want pose at x=%v unchanged", tc.time, p, tc.x)
394			}
395			approxEq(t, "variance unchanged", p.Variance, 1.0)
396		}
397		lms, _ = m.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
398		if len(lms) != 1 || lms[0].ID != "L" {
399			t.Fatalf("landmarks after rejected corrections = %v, want only L", lms)
400		}
401		approxEq(t, "L x unchanged", lms[0].X, 0.5)
402		approxEq(t, "L y unchanged", lms[0].Y, 0)
403		if lms[0].Count != 2 {
404			t.Fatalf("L count after rejected corrections = %d, want 2", lms[0].Count)
405		}
406		h, err := m.LandmarkAppearances("L")
407		if err != nil {
408			t.Fatal(err)
409		}
410		if len(h.Appearances) != 1 || !h.Appearances[0].Active ||
411			!h.Appearances[0].HasFirstSeen || h.Appearances[0].FirstSeenTime != 100 ||
412			h.Appearances[0].Landmark.Count != 2 {
413			t.Fatalf("L appearance after rejected corrections = %+v", h.Appearances)
414		}
415		if _, err := m.LandmarkAppearances("ZZ"); !errors.Is(err, ErrLandmarkNotFound) {
416			t.Fatalf("stranger landmark ZZ leaked into map: %v", err)
417		}
418		if recs, _ := m.Corrections(); len(recs) != 0 {
419			t.Fatalf("correction records after rejections = %v, want none", recs)
420		}
421	
422		// 同一校正标识未被失败的提交消耗：把目标改成不再冲突的恒等位置
423		// 校正后仍可用同一标识成功，证明此前拒绝确实只针对已接受观测引起
424		// 的冲突，而非标识或锚点状态被污染。
425		okReq := Correction{
426			ID:     "c-loop",
427			Anchor: 200,
428			Target: CorrectionTarget{X: 0, Y: 0, Heading: 0, Variance: 0},
429		}
430		rec, err := m.Correct(okReq)
431		if err != nil {
432			t.Fatalf("identity correction after conflicts: %v", err)
433		}
434		if len(rec.Landmarks) != 1 || rec.Landmarks[0].ID != "L" || rec.Landmarks[0].After.Count != 2 {
435			t.Fatalf("identity correction record = %+v", rec.Landmarks)
436		}
437		approxEq(t, "L x after identity correction", rec.Landmarks[0].After.X, 0.5)
438	}
439

