1	package posemap
2	
3	// occurrence.go 承载“观测按所在帧时间归入当时那次出现”这一业务规则，
4	// 供观测重放器（observationReplay，见 replay.go）归组使用；提交回环校正
5	// 与打开地图时的核对都经由重放器共享这同一份时间边界判断，两处始终一致。
6	
7	// occurrenceWindow 是一次出现接纳观测的时间边界：
8	//
9	//   - 已知首次观测时间的出现只接纳不早于该时间的观测（端点包含）；
10	//   - 已失效的出现仍接纳失效时间上的观测（端点包含），之后的观测不再
11	//     属于它；
12	//   - 仍有效的出现没有失效时间上界；
13	//   - 首次观测时间未知（旧文件缺少逐帧来源）的出现没有下界，继续接纳
14	//     更早的历史观测，不把零当作补造的开始时间。
15	//
16	// 同一路标各次出现的时间区间互不重叠（打开文件时由 validateLoaded 强制
17	// 校验，区间矛盾的文件按损坏拒绝），因此任一时刻至多有一次出现接纳
18	// 观测；旧观测永远归入它所在帧当时的那次出现，不因后来出现了更新的
19	// 有效记录而改属。
20	type occurrenceWindow struct {
21		hasFirstSeen  bool
22		firstSeenTime int64
23		active        bool
24		invalidTime   int64
25	}
26	
27	// owns 判断时间 t 的观测是否属于这次出现。
28	func (w occurrenceWindow) owns(t int64) bool {
29		if w.hasFirstSeen && t < w.firstSeenTime {
30			return false
31		}
32		if !w.active && t > w.invalidTime {
33			return false
34		}
35		return true
36	}
37	
38	// occurrenceNumberAt 把时间 t 的一次观测归入当时的那次出现，返回 1 起
39	// 的出现编号；没有任何出现接纳时返回 0。
40	func occurrenceNumberAt(wins []occurrenceWindow, t int64) int {
41		for i, w := range wins {
42			if w.owns(t) {
43				return i + 1
44			}
45		}
46		return 0
47	}
48	
49	// window 返回该出现状态对应的时间边界。
50	func (o *occurrenceState) window() occurrenceWindow {
51		return occurrenceWindow{
52			hasFirstSeen:  o.hasFirstSeen,
53			firstSeenTime: o.firstSeenTime,
54			active:        o.active,
55			invalidTime:   o.invalidTime,
56		}
57	}
58	
59	// occurrenceWindows 返回该路标各次出现的时间边界（编号即下标+1），供
60	// 重放器登记归属边界使用。
61	func (lm *landmarkState) occurrenceWindows() []occurrenceWindow {
62		wins := make([]occurrenceWindow, 0, len(lm.appearances))
63		for _, o := range lm.appearances {
64			wins = append(wins, o.window())
65		}
66		return wins
67	}
68	
69	// occurrenceWindowsOf 从文件记录中提取一个路标各次出现的时间边界，供
70	// 打开文件时登记重放器的归属边界使用。旧版平铺路标视为一次首次观测时间未知、
71	// 仍有效的第 1 次出现（无下界、无上界）。
72	func occurrenceWindowsOf(lm landmarkJSON) []occurrenceWindow {
73		if len(lm.Occurrences) == 0 {
74			return []occurrenceWindow{{active: true}}
75		}
76		wins := make([]occurrenceWindow, 0, len(lm.Occurrences))
77		for _, oj := range lm.Occurrences {
78			wins = append(wins, occurrenceWindow{
79				hasFirstSeen:  oj.HasFirstSeen,
80				firstSeenTime: oj.FirstSeenTime,
81				active:        oj.Active,
82				invalidTime:   oj.InvalidTime,
83			})
84		}
85		return wins
86	}
