	}
	lms := activeLandmarks(t, m)
	if len(lms) != 1 || lms["L"].X != 12 {
		t.Fatalf("active landmarks = %v", lms)
	}

	// 第二次校正不改写既有记录，且新记录仍区分出现编号。
	rec2, err := m.Correct(Correction{ID: "c2", Anchor: 300, Target: CorrectionTarget{X: 13, Y: 0}})
